try_change.source:
valid_name() {
  case "$1" in
    *'
'*) return 1 ;;
  esac
  printf '%s\n' "$1" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}$'
}
snapshot() {
  if cat -- "$1"; then :; else return 2; fi
}
same_files() {
  left_value=$(snapshot "$1")
  capture_status=$?
  if test "$capture_status" -ne 0; then return 2; fi
  right_value=$(snapshot "$2")
  capture_status=$?
  if test "$capture_status" -ne 0; then return 2; fi
  test "$left_value" = "$right_value"
}
if same_files iris lily; then printf 'Practice same\n'; else printf 'Practice drift\n'; fi

