        "valid_name() {\n  case \"$1\" in\n    *'\n'*) return 1 ;;\n  esac\n  printf '%s\\n' \"$1\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}$'\n}\nsnapshot() {\n  if cat -- \"$1\"; then printf '.'; else return 2; fi\n}\nsame_files() {\n  left_value=$(snapshot \"$1\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  right_value=$(snapshot \"$2\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  test \"$left_value\" = \"$right_value\"\n}\nusage() { printf 'Usage: rollout preview-or-apply PLAN REPORT\\n' >&2; exit 2; }\nbad_line() { printf 'Line %s: %s\\n' \"$number\" \"$1\" >&2; exit 2; }\nif test \"$#\" -ne 3; then usage; fi\nmode=$1\nplan_file=$2\nreport_file=$3\ncase \"$mode\" in preview|apply) : ;; *) usage ;; esac\nif valid_name \"$plan_file\" && valid_name \"$report_file\"; then :; else printf 'Invalid files\\n' >&2; exit 2; fi\nif test \"$plan_file\" = \"$report_file\" || test \"$plan_file\" = keep.txt || test \"$report_file\" = keep.txt; then\n  printf 'Invalid files\\n' >&2\n  exit 2\nfi\nif test -f \"$plan_file\"; then :; else printf 'Missing plan\\n' >&2; exit 2; fi\nnumber=0\nchanged=0\nunchanged=0\nreport_text=''\nstaged=()\nseen=( \"$plan_file\" \"$report_file\" keep.txt )\nwhile IFS= read -r line || test -n \"$line\"; do\n  number=$((number+1))\n  if test \"$number\" -gt 8; then bad_line 'too many jobs'; fi\n  if printf '%s\\n' \"$line\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}[|][a-z][a-z0-9.-]{0,11}[|][a-z][a-z0-9.-]{0,11}$'; then :; else bad_line 'malformed job'; fi\n  desired=$(printf '%s\\n' \"$line\" | cut -d '|' -f 1)\n  current=$(printf '%s\\n' \"$line\" | cut -d '|' -f 2)\n  rollback=$(printf '%s\\n' \"$line\" | cut -d '|' -f 3)\n  for name in \"$desired\" \"$current\" \"$rollback\"; do\n    for used in \"${seen[@]}\"; do\n      if test \"$name\" = \"$used\"; then bad_line 'conflicting paths'; fi\n    done\n    seen=( \"${seen[@]}\" \"$name\" )\n  done\n  if test -f \"$desired\"; then :; else bad_line 'missing desired'; fi\n  if test -f \"$current\"; then :; else bad_line 'missing current'; fi\n  if same_files \"$desired\" \"$current\"; then\n    decision=same\n    unchanged=$((unchanged+1))\n  else\n    comparison_status=$?\n    if test \"$comparison_status\" -ne 1; then bad_line 'cannot compare'; fi\n    decision=change\n    changed=$((changed+1))\n  fi\n  staged=( \"${staged[@]}\" \"$decision|$desired|$current|$rollback\" )\n  report_text=$report_text$decision'|'$current'\n'\ndone < \"$plan_file\"\nreport_text=$report_text'Changes:'$changed'\nUnchanged:'$unchanged'\n'\nif test \"$mode\" = preview; then printf 'Preview\\n%s' \"$report_text\"; exit 0; fi\nfor job in \"${staged[@]}\"; do\n  decision=$(printf '%s\\n' \"$job\" | cut -d '|' -f 1)\n  desired=$(printf '%s\\n' \"$job\" | cut -d '|' -f 2)\n  current=$(printf '%s\\n' \"$job\" | cut -d '|' -f 3)\n  rollback=$(printf '%s\\n' \"$job\" | cut -d '|' -f 4)\n  if test \"$decision\" = change; then\n    cat -- \"$current\" > \"$rollback\"\n    cat -- \"$desired\" > \"$current\"\n  fi\ndone\nprintf '%s' \"$report_text\" > \"$report_file\"\nprintf 'Applied:%s\\nUnchanged:%s\\n' \"$changed\" \"$unchanged\"\nexit 0\n"
      ],
      "prerequisites": [
        "shell-trim-options",
        "shell-trim-manifest",
        "shell-snapshot-audit"
      ],
      "explanation": "Preflight the interface and required files. Capture after a checked read with a fixed nonLF suffix; compare the whole values or remove that exact suffix with the reviewed literal form. Preserve all bytes. For rollout, validate every row and every path before writing, retain changed old-current data independently and leave unchanged rollback data intact. Staged and repeated-read approaches are both valid under disjoint immutable inputs. This is final-state/preflight behavior; operation order, atomic rename, races and Stop rollback are not graded.",
      "hints": [
        "A normal capture can erase the only difference: trailing LF. Preserve that boundary before comparing.",
        "Separate input trouble from useful same/different information; save helper status before another command replaces it.",
        "Validate all paths before output redirects. Preserve old rollback data for unchanged jobs; a late predictable refusal must leave every file intact."
      ],
      "teaching": {
        "prerequisite_note": "First finish the earlier quoted capture, IFS read, functions/status, arrays, loop and literal-interface lessons. This unit teaches a lossless sentinel comparison before using it in a rollout. No wc, cmp, diff, trap or host utility is available.",
        "concepts": [
          {
            "title": "Compare contents, not names or first lines",
            "text": "Two different filenames may hold identical data. A same/different decision uses every byte in this simulator's bounded valid UTF8 text, including blank lines, CR, backslashes and trailing LF. Binary and NUL files are outside this model."
          },
          {
            "title": "Why the same suffix preserves trailing LF",
            "text": "Command capture removes all final LF bytes. Append one fixed nonLF marker inside each capture, after cat succeeds, so the final character is not LF. Compare the complete marked values. The same suffix is safe even when that marker occurs in the data; it is not written into files."
          },
          {
            "title": "A nonzero result can be useful information",
            "text": "The comparison helper returns0 for equal,1 for different,2 for input trouble. Save $? immediately if you need to distinguish them. A later successful printf must not conceal a failed read. Use explicit if/else; no errexit or trap is assumed."
          },
          {
            "title": "Read preserves a final fragment differently",
            "text": "IFS= read -r preserves edge spaces and backslashes, removes one consumed LF, and reports0 only when it found LF. A nonempty last fragment is still assigned with status1; empty EOF assigns empty/status1. A read-based alternative must put LF back only for successful complete-line reads."
          },
          {
            "title": "Decide the whole plan before opening outputs",
            "text": "Validate the interface, every row, required inputs and all path conflicts before changing a file. A changed job needs an independent old-current rollback. An unchanged job preserves the existing rollback or its absence. Protected input and keep.txt must remain intact."
          },
          {
            "title": "What this preflight promise does not mean",
            "text": "A predictable validation refusal preserves every file. Ordinary writes are not atomic rename or a lock: Stop or a resource failure during writing is not promised to roll back earlier work. Completion checks current outcomes, not a transcript count or required command spelling."
          }
        ],
        "example": "valid_name() {\n  case \"$1\" in\n    *'\n'*) return 1 ;;\n  esac\n  printf '%s\\n' \"$1\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}$'\n}\nsnapshot() {\n  if cat -- \"$1\"; then printf '.'; else return 2; fi\n}\nsame_files() {\n  left_value=$(snapshot \"$1\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  right_value=$(snapshot \"$2\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  test \"$left_value\" = \"$right_value\"\n}\nif test -f plum && test -f dusk; then :; else printf 'Practice input missing\\n' >&2; exit 2; fi\nif same_files plum dusk; then printf 'Practice unchanged\\n'; else\n  cat -- dusk > pearl\n  cat -- plum > dusk\n  printf 'Practice changed\\n'\nfi\n",
        "inputs": "These practice-only files and values are unrelated to assignment records. Each Run starts with this separate fixture.",
        "try_change": "Change only same_files plum dusk to same_files plum plum and Run. The desired file is now compared with itself, so the old current is wrongly skipped. Restore dusk to repair.",
