      "solution": [
        "valid_name() {\n  case \"$1\" in\n    *'\n'*) return 1 ;;\n  esac\n  printf '%s\\n' \"$1\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}$'\n}\nsnapshot() {\n  if cat -- \"$1\"; then printf '.'; else return 2; fi\n}\nsame_files() {\n  left_value=$(snapshot \"$1\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  right_value=$(snapshot \"$2\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  test \"$left_value\" = \"$right_value\"\n}\nif test \"$#\" -ne 2; then printf 'Usage: compare LEFT RIGHT\\n' >&2; exit 2; fi\nif valid_name \"$1\" && valid_name \"$2\"; then :; else printf 'Invalid files\\n' >&2; exit 2; fi\nif test -f \"$1\"; then :; else printf 'Missing left\\n' >&2; exit 2; fi\nif test -f \"$2\"; then :; else printf 'Missing right\\n' >&2; exit 2; fi\nif same_files \"$1\" \"$2\"; then\n  printf 'Same\\nLeft:%s\\nRight:%s\\n' \"$1\" \"$2\"\n  exit 0\nelse\n  comparison_status=$?\n  if test \"$comparison_status\" -ne 1; then printf 'Cannot compare\\n' >&2; exit 2; fi\n  printf 'Different\\nLeft:%s\\nRight:%s\\n' \"$1\" \"$2\"\n  exit 1\nfi\n"
      ],
