        "valid_name() {\n  case \"$1\" in\n    *'\n'*) return 1 ;;\n  esac\n  printf '%s\\n' \"$1\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}$'\n}\nsnapshot() {\n  if cat -- \"$1\"; then printf '.'; else return 2; fi\n}\nsame_files() {\n  left_value=$(snapshot \"$1\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  right_value=$(snapshot \"$2\")\n  capture_status=$?\n  if test \"$capture_status\" -ne 0; then return 2; fi\n  test \"$left_value\" = \"$right_value\"\n}\nusage() { printf 'Usage: rollout preview-or-apply PLAN REPORT\\n' >&2; exit 2; }\nbad_line() { printf 'Line %s: %s\\n' \"$number\" \"$1\" >&2; exit 2; }\nif test \"$#\" -ne 3; then usage; fi\nmode=$1\nplan_file=$2\nreport_file=$3\ncase \"$mode\" in preview|apply) : ;; *) usage ;; esac\nif valid_name \"$plan_file\" && valid_name \"$report_file\"; then :; else printf 'Invalid files\\n' >&2; exit 2; fi\nif test \"$plan_file\" = \"$report_file\" || test \"$plan_file\" = keep.txt || test \"$report_file\" = keep.txt; then\n  printf 'Invalid files\\n' >&2\n  exit 2\nfi\nif test -f \"$plan_file\"; then :; else printf 'Missing plan\\n' >&2; exit 2; fi\nnumber=0\nchanged=0\nunchanged=0\nreport_text=''\nstaged=()\nseen=( \"$plan_file\" \"$report_file\" keep.txt )\nwhile IFS= read -r line || test -n \"$line\"; do\n  number=$((number+1))\n  if test \"$number\" -gt 8; then bad_line 'too many jobs'; fi\n  if printf '%s\\n' \"$line\" | grep -Eq -- '^[a-z][a-z0-9.-]{0,11}[|][a-z][a-z0-9.-]{0,11}[|][a-z][a-z0-9.-]{0,11}$'; then :; else bad_line 'malformed job'; fi\n  desired=$(printf '%s\\n' \"$line\" | cut -d '|' -f 1)\n  current=$(printf '%s\\n' \"$line\" | cut -d '|' -f 2)\n  rollback=$(printf '%s\\n' \"$line\" | cut -d '|' -f 3)\n  for name in \"$desired\" \"$current\" \"$rollback\"; do\n    for used in \"${seen[@]}\"; do\n      if test \"$name\" = \"$used\"; then bad_line 'conflicting paths'; fi\n    done\n    seen=( \"${seen[@]}\" \"$name\" )\n  done\n  if test -f \"$desired\"; then :; else bad_line 'missing desired'; fi\n  if test -f \"$current\"; then :; else bad_line 'missing current'; fi\n  if same_files \"$desired\" \"$current\"; then\n    decision=same\n    unchanged=$((unchanged+1))\n  else\n    comparison_status=$?\n    if test \"$comparison_status\" -ne 1; then bad_line 'cannot compare'; fi\n    decision=change\n    changed=$((changed+1))\n  fi\n  staged=( \"${staged[@]}\" \"$decision|$desired|$current|$rollback\" )\n  report_text=$report_text$decision'|'$current'\n'\ndone < \"$plan_file\"\nreport_text=$report_text'Changes:'$changed'\nUnchanged:'$unchanged'\n'\nif test \"$mode\" = preview; then printf 'Preview\\n%s' \"$report_text\"; exit 0; fi\nfor job in \"${staged[@]}\"; do\n  decision=$(printf '%s\\n' \"$job\" | cut -d '|' -f 1)\n  desired=$(printf '%s\\n' \"$job\" | cut -d '|' -f 2)\n  current=$(printf '%s\\n' \"$job\" | cut -d '|' -f 3)\n  rollback=$(printf '%s\\n' \"$job\" | cut -d '|' -f 4)\n  if test \"$decision\" = change; then\n    cat -- \"$current\" > \"$rollback\"\n    cat -- \"$desired\" > \"$current\"\n  fi\ndone\nprintf '%s' \"$report_text\" > \"$report_file\"\nprintf 'Applied:%s\\nUnchanged:%s\\n' \"$changed\" \"$unchanged\"\nexit 0\n"
      ],
